/**
 * Builds CREATE TABLE statements from a structured spec. Shared so the UI can
 * preview exactly the SQL the server will run.
 */

export const FK_ACTIONS = ['NO ACTION', 'RESTRICT', 'CASCADE', 'SET NULL', 'SET DEFAULT'] as const;
export type FkAction = (typeof FK_ACTIONS)[number];

export interface NewColumn {
  name: string;
  /** A SQL type such as `text`, `numeric(10,2)`, `timestamptz`, `int[]` or `public.mood`. */
  type: string;
  nullable: boolean;
  primaryKey: boolean;
  unique: boolean;
  /** Auto-increment: GENERATED BY DEFAULT AS IDENTITY (integer types only). */
  identity: boolean;
  /** A SQL expression, e.g. `now()`, `0`, `'draft'`. Empty for none. */
  default: string;
  references: { schema: string; table: string; column: string; onDelete: FkAction; onUpdate: FkAction } | null;
  comment: string;
}

export interface NewTable {
  schema: string;
  name: string;
  columns: NewColumn[];
  comment: string;
}

export const quoteIdent = (name: string): string => `"${name.replace(/"/g, '""')}"`;
export const quoteLiteral = (s: string): string => `'${s.replace(/'/g, "''")}'`;

/** Letters, digits, spaces, dots, (n[,m]) modifiers and [] — enough for any type, no room for injection. */
const TYPE_RE = /^[A-Za-z_][\w .$]*(\(\s*\d+\s*(,\s*\d+\s*)?\))?[\w ]*(\[\d*\]\s*)*$/;
export const isValidType = (t: string): boolean => TYPE_RE.test(t.trim()) && t.trim().length <= 128;

const INTEGER_TYPES = new Set(['smallint', 'integer', 'int', 'int2', 'int4', 'int8', 'bigint']);
export const isIntegerType = (t: string): boolean => INTEGER_TYPES.has(t.trim().toLowerCase());

/** Problems that would make the statement fail, in UI-friendly words. Empty when valid. */
export function validateColumn(c: NewColumn, label: string): string[] {
  const errors: string[] = [];
  if (!c.name.trim()) errors.push(`${label}: needs a name.`);
  if (c.name.length > 63) errors.push(`${label}: names are limited to 63 characters.`);
  if (!isValidType(c.type)) errors.push(`${label}: "${c.type}" is not a valid type.`);
  if (c.identity && !isIntegerType(c.type)) errors.push(`${label}: auto-increment needs an integer type.`);
  if (c.identity && c.default.trim()) errors.push(`${label}: auto-increment columns can't have a default.`);
  if (c.references && (!c.references.table || !c.references.column)) errors.push(`${label}: pick the referenced table and column.`);
  return errors;
}

export function validateTable(t: NewTable): string[] {
  const errors: string[] = [];
  if (!t.name.trim()) errors.push('Give the table a name.');
  if (t.name.length > 63) errors.push('Table names are limited to 63 characters.');
  if (!t.columns.length) errors.push('Add at least one column.');
  const seen = new Set<string>();
  t.columns.forEach((c, i) => {
    const label = c.name.trim() || `Column ${i + 1}`;
    if (c.name.trim() && seen.has(c.name)) errors.push(`${label}: duplicate column name.`);
    seen.add(c.name);
    errors.push(...validateColumn(c, label));
  });
  return errors;
}

/** `"name" type [identity] [default] [not null] [primary key] [unique]` for CREATE / ADD COLUMN. */
export function columnDefinition(c: NewColumn, inlinePrimaryKey: boolean): string {
  let line = `${quoteIdent(c.name)} ${c.type.trim()}`;
  if (c.identity) line += ' GENERATED BY DEFAULT AS IDENTITY';
  if (c.default.trim() && !c.identity) line += ` DEFAULT ${c.default.trim()}`;
  if (!c.nullable && !inlinePrimaryKey) line += ' NOT NULL';
  if (inlinePrimaryKey) line += ' PRIMARY KEY';
  else if (c.unique) line += ' UNIQUE';
  return line;
}

export function foreignKeyClause(column: string, r: NonNullable<NewColumn['references']>): string {
  let line = `FOREIGN KEY (${quoteIdent(column)}) REFERENCES ${quoteIdent(r.schema)}.${quoteIdent(r.table)} (${quoteIdent(r.column)})`;
  if (r.onDelete !== 'NO ACTION') line += ` ON DELETE ${r.onDelete}`;
  if (r.onUpdate !== 'NO ACTION') line += ` ON UPDATE ${r.onUpdate}`;
  return line;
}

/** The CREATE TABLE (plus COMMENT ON) statements for a spec. Call validateTable first. */
export function createTableSql(t: NewTable): string {
  const table = `${quoteIdent(t.schema)}.${quoteIdent(t.name)}`;
  const pk = t.columns.filter((c) => c.primaryKey);
  const lines: string[] = [];

  for (const c of t.columns) lines.push(columnDefinition(c, pk.length === 1 && c.primaryKey));
  if (pk.length > 1) lines.push(`PRIMARY KEY (${pk.map((c) => quoteIdent(c.name)).join(', ')})`);
  for (const c of t.columns) if (c.references) lines.push(foreignKeyClause(c.name, c.references));

  let sql = `CREATE TABLE ${table} (\n  ${lines.join(',\n  ')}\n);`;
  if (t.comment.trim()) sql += `\n\nCOMMENT ON TABLE ${table} IS ${quoteLiteral(t.comment.trim())};`;
  for (const c of t.columns) {
    if (c.comment.trim()) sql += `\nCOMMENT ON COLUMN ${table}.${quoteIdent(c.name)} IS ${quoteLiteral(c.comment.trim())};`;
  }
  return `${sql}\n`;
}

export const emptyColumn = (over: Partial<NewColumn> = {}): NewColumn => ({
  name: '',
  type: 'text',
  nullable: true,
  primaryKey: false,
  unique: false,
  identity: false,
  default: '',
  references: null,
  comment: '',
  ...over,
});
